    if line.startswith('Application application_') and ',' in line:
        step_syslog['application_id'] = line.split(',')[1].strip()
    elif line.startswith('Counters: '):
        step_syslog['counters'] = _parse_counters(line)
    elif line.startswith('Error: '):
        step_syslog['errors'] = line.split('Error: ')[1].strip()
    elif line.startswith('Streaming Command Failed!') and 'job_id' not in step_syslog:
        step_syslog['job_id'] = line.split('job_id ')[1].split(' ')[0]
    elif line.startswith('Streaming Command Failed!') and 'output_dir' not in step_syslog:
