if len(self) == 2:
    return self.merge(self[0], self[1])
if len(self) == 3:
    return self.merge(self.merge(self[0], self[1]), self[2])
if len(self) == 4:
    return self.merge(self.merge(self.merge(self[0], self[1]), self[2]), self[3])
if len(self) == 5:
    return self.merge(self.merge(self.merge(self.merge(self[0], self[1]), self[2]), self[3]), self[4])
if len(self) == 6:
    return self.merge(self.merge(self.merge(self.merge(self.merge(self[0], self[1]), self[2]), self[3]),self[4]), self[5])
if len(self) == 7:
