"""This function calculates and returns the highest and lowest notes from a list of notes.


:param self: Bar, an instance of the Bar class.
:return: tuple of ints. A tuple containing the highest and lowest notes.

"""
highest = 0
lowest = 128
for note in self.notes:
    if note.note > highest:
        highest = note.note
    if note.note < lowest:
        lowest = note.note
return (highest, lowest)

"""This function takes a stream of JSON data and parses it into a PolicyDocument object. It first checks if the stream is a string, and if so, it loads the JSON data into a dictionary. Otherwise, it loads the JSON data as file stream. Finally, it creates a PolicyDocument object using the parsed statements and version from the JSON dictionary.

:param stream: The input stream of JSON data.
:return: PolicyDocument. The parsed PolicyDocument object.
"""
if isinstance(stream, str):
    data = json.loads(stream)
else:
    data = json.load(stream)
statements = []
for statement in data['Statement']:
    statements.append(Statement(statement))
return PolicyDocument(data['Version'], statements)

"""This function takes an object and converts every list and dict into its read-only counterpart in a nested structure of lists, dicts, and tuples. It does not modify the original object but returns the converted structure.

:param o: Any data type. The object to be made read-only.
:return: Any data type. The converted read-only structure.
"""
if isinstance(o, list):
    return tuple(make_read_only(i) for i in o)
elif isinstance(o, dict):
    return frozenset((make_read_only(k), make_read_only(v)) for k, v in o.items())
else:
    return o

"""This function adds a rule to the Lifecycle configuration of an object.

:param self: Lifecycle. An instance of Lifecycle class
:param id: str [optional]. Unique identifier for the rule. The value cannot be longer than 255 characters. This value is optional. The server will generate a unique value for the rule if no value is provided.
:param prefix: str. Prefix identifying one or more objects to which the rule applies.
:param status: str. If 'Enabled', the rule is currently being applied. If 'Disabled', the rule is not currently being applied.
:param expiration: int. Indicates the lifetime, in days, of the objects that are subject to the rule. The value must be a non-zero positive integer. An Expiration object instance is also perfect.
:param transition: Transitions. Indicates when an object transitions to a different storage class.
:return: No return values.
"""
if id is None:
    id = str(uuid.uuid4())
if status not in ['Enabled', 'Disabled']:
    raise ValueError('status must be one of: Enabled, Disabled')
if expiration is not None and not isinstance(expiration, int):
    raise TypeError('expiration must be an integer')
if expiration is not None and expiration <= 0:
    raise ValueError('expiration must be a non-zero positive integer')
if transition is not None and not isinstance(transition, Transitions):
    raise TypeError('transition must be an instance of Transitions class')
if transition is not None and transition.days is not None and transition.days <= 0:
    raise ValueError('transition.days must be a non-zero positive integer')
if transition is not None and transition.date is not None and transition.date < datetime.datetime.now():
    raise ValueError('transition.date must be a date in the future')
if transition is not None and transition.storage_class not in ['GLACIER', 'STANDARD_IA']:
    raise ValueError('transition.storage_class must be one of: GLACIER, STANDARD_IA')
if transition is not None and transition.storage_class == 'GLACIER' and transition.days is None:
    raise ValueError('transition.days must be specified when transition.storage_class is GLACIER')
if transition is not None and transition.storage_class == 'STANDARD_IA' and transition.days is None:
    raise ValueError('transition.days must be specified when transition.storage_class is STANDARD_IA')
if transition is not None and transition.storage_class == 'STANDARD_IA' and transition.date is not None:
    raise ValueError('transition.date must be None when transition.storage_class is STANDARD_IA')
if transition is not None and transition.storage_class == 'GLACIER' and transition.date is not None:
    raise ValueError('transition.date must be None when transition.storage_class is GLACIER')
if transition is not None and transition.date is not None and transition.days is not None:
    raise ValueError('transition.date and transition.days cannot both be specified')
if transition is not None and transition.date is not None and transition.date < datetime.datetime.now():
    raise ValueError(
        'transition.date must be a date in the future')
if transition is not None and transition.date is not None and transition.date > datetime.datetime.now() + datetime.timedelta(days=1095):
    raise ValueError(
        'transition.date must be a date less than 3 years from now')
if transition is not None and transition.date is not None and transition.date < datetime.datetime(2006, 01, 01):
    raise ValueError(
        'transition.date must be a date after 2006-01-01')
if transition is not None and transition.date is not None and transition.date > datetime.datetime(2038, 01, 19):
    raise ValueError(
        'transition.date must be a date before 2038-01-19')
if transition is not None and transition.days is not None and transition.days > 3650:
    raise ValueError('transition.days must be less than 3650')
if transition is not None and transition.days is not None and transition.days < 1:
    raise ValueError('transition.days must be greater than 0')
if transition is not None and transition.days is not None and transition.days % 1 != 0:
    raise ValueError('transition.days must be an integer')
if transition is not None and transition.storage_class is None:
    raise ValueError('transition.storage_class must be specified')
if transition is not None and transition.storage_class is not None and transition.storage_class not in ['GLACIER', 'STANDARD_IA']:
    raise ValueError('storage_class must be one of: GLACIER, STANDARD_IA')
if transition is not None and transition.storage_type is not None and transition.storage_type not in ['Standard', 'S3Standard']:
    raise ValueError('transition.storage_type must be one of: Standard, S3Standard')
if transition is not None and transition.storage_type is not None and transition.storage_type == 'S3Standard' and transition.storage_class != 'STANDARD_IA':
    raise ValueError('transition.storage_type must be S3Standard only when transition.storage_class is STANDARD_IA')
if transition is not None and transition.storage_type is not None and transition.storage_type == 'Standard' and transition.storage_class != 'GLACIER':
    raise ValueError('transition.storage_type must be Standard only when transition.storage_class is GLACIER')
if transition is not None and transition.date is not None and transition.date < datetime.datetime.now() + datetime.timedelta(days=transition.days):
    raise ValueError(
        'transition.date must be a date in the future')
if transition is not None and transition.date > datetime.datetime.now() + datetime.timedelta(days=1095):
    raise Exception(
        'transition.date must be a date less than 3 years from now')
if transition is not None and transition.date < datetime.datetime(2006, 01, 01):
    raise Exception(
        'transition.date must be a date after 2006-01-01')
if transition is not None:
    transition = transition.to_xml()
self.lifecycle_config.append(
    {'ID': id, 'Prefix': prefix, 'Status': status, 'Expiration': expiration, 'Transitions': transition})

