:param self: ConfigSchema. An instance of the ConfigSchema class.
:param values: dict. A dictionary containing the values to be validated against the config schema.
:return: tuple. A tuple containing the cleaned values in the `result` dictionary and the errors in the `errors` dictionary.
"""
result = {}
errors = {}
for key, value in values.items():
    if key in self.schema:
        try:
            result[key] = self.schema[key].deserialize(value)
        except ValidationError as e:
            errors[key] = e.args[0]
    else:
        errors[key] = f'No such config option: {key}'
for key in self.schema:
    if key in self.schema_defaults and key not in result:
        result[key] = self.schema_defaults[key]
for key in self.schema:
    if key in self.schema_descriptions and key not in result:
        result[key] = self.schema_descriptions[key]
for key in self.schema:
    if key in self.schema_descriptions and key not in result:
            result[key] = self.schema_descriptions[key]
for key in self.schema:
    if key in self.deprecated:
        if key in result:
            errors[key] = f'Config option is deprecated and will be removed in a future release: {key}'
        else:
            result.pop(key, None)
return result, errors

