    return
if align:
    start = input_offset + (chunk_size - overlap_size) * (input_offset // (chunk_size - overlap_size))
else:
    start = input_offset
while start < input_offset + input_size - chunk_size + 1:
    yield (start, start + chunk_size)
    start += chunk_size - overlap_size
