"""This function returns the major key and its relative minor key corresponding to the number of accidentals provided as input.


:param accidentals: int. The number of accidentals. It defaults to 0 if not specified.
:return: tuple of str. The major key corresponding to the accidentals and its relative minor key.

"""
if accidentals == 0:
    return 'C', 'Am'
elif accidentals == 1:
    return 'C#', 'Bm'
elif accidentals == 2:
    return 'D', 'A'
elif accidentals == 3:
    return 'D#', 'A#m'
elif accidentals == 4:
    return 'E', 'B'
elif accidentals == 5:
    return 'F', 'E'
elif accidentals == 6:
    return 'F#', 'Cm'
elif accidentals == 7:
    return 'G', 'F#m'
elif accidentals == 8:
    return 'G#', 'C#m'
elif accidentals == 9:
    return 'A', 'Gm'
elif accidentals == 10:
    return 'A#', 'Dm'
elif accidentals == 11:
    return 'B', 'A#m'
else:
    raise ValueError('The number of accidentals must be between 0 and 11.')

